        b.innerHTML = icon(preset?.icon || c.icon || "chevronRight", 15) + `<span>${esc(preset?.label || deEmoji(c.title))}</span>` + (id2 === "analyze" ? '<span class="analyze-badge" id="analyzeBadge">0</span>' : "");
        host2.appendChild(b);
